// A model's own level is its fallback entry's. `--model` runs every model at the route's.
const own = (model: string) => (flag === undefined ? ReviewPlan.ownLevel(effective, model) : undefined);
// The level each of `names` runs at when `routed` runs them in that order, as `routeInOrder` gives it.
const runsAt = (routed: ModelRoute | undefined, names: readonly string[], ownOf: typeof own) => {
	const run = routeInOrder(
		names.map((model) => ({ model, thinking: ownOf(model) })),
		routed?.thinking,
	);
	return new Map(run.route.map((each) => [each.model, each.thinking ?? run.thinking]));
};
for (const name of [...route, ...accept]) parse(name);
const entry = (name: string) => {
	const { provider, modelId } = parse(name);
	return catalog.find((model) => model.provider === provider && model.id === modelId);
};
const usable = (name: string) => entry(name) !== undefined && Object.hasOwn(credentials, entry(name)!.provider);
const planned = (names: readonly string[]) =>
	names.map(
		(model): PlannedModel => ({
			model,
			credential: credentials[parse(model).provider] ?? "none",
			...(entry(model) === undefined ? {} : { family: sameModel(entry(model)!.name).split(" ")[0]! }),
			...(own(model) === undefined ? {} : { thinking: own(model) }),
		}),
	);

export function describeLineage({ model, wanted, by, moved, outside, thinking, answeredAt }: CheckLineage): string {
	const routed = by === "derived" ? "derived, since no model of its route has credentials" : `set by ${by}`;
	const why =
		moved === undefined ? routed : `moved from ${moved.from} to ${moved.to} by ${moved.by}, whose route is ${routed}`;
	const policy = wanted === undefined ? "where policy" : `where policy wants ${wanted} and`;
	const reasoning =
		thinking === undefined
			? ""
			: `; thinking ${thinking.level} set by ${thinking.by}; policy wants ${thinking.wanted}`;
	const own = answeredAt === undefined ? "" : `; it answered at thinking ${answeredAt}`;
	return `on ${model}, ${why}, ${policy} ${outside ? "does not accept" : "accepts"} ${model}${reasoning}${own}`;

// Objects merge key by key; anything else, arrays included, is replaced by the nearer value. Merged objects have no
// prototype, so a lens named `constructor` or `toString` is looked up like any other.
function merge(under: Plain, over: Plain): Plain {
	const merged: Plain = Object.assign(Object.create(null), under);
	for (const [key, value] of Object.entries(over)) {
		const below = merged[key];
		merged[key] = isPlain(below) && isPlain(value) ? merge(below, value) : isPlain(value) ? merge({}, value) : value;
	}
	return merged;
}
